style.css:
/* Rouge Pink Dark Mode Theme for YouTube */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("youtube.com") {
/* General Background */
  body {
    background-color: #1a1a1a !important;
    color: #f8d3da !important;
  }

  #container, #content, #masthead-container {
    background-color: #1a1a1a !important;
    color: #f8d3da !important;
  }

  /* Top Navigation Bar */
  #masthead {
    background-color: #2e2e2e !important;
    border-bottom: 1px solid #e34b73 !important;
  }

  /* Sidebar and Menus */
  #guide {
    background-color: #2e2e2e !important;
    color: #f8d3da !important;
  }

  ytd-mini-guide-entry-renderer, ytd-guide-entry-renderer {
    color: #f8d3da !important;
  }

  /* Hover Effects */
  ytd-guide-entry-renderer:hover, 
  ytd-mini-guide-entry-renderer:hover {
    background-color: #e34b73 !important;
    color: #1a1a1a !important;
  }

  /* Video Thumbnails */
  ytd-thumbnail, ytd-thumbnail-overlay {
    background-color: #2e2e2e !important;
  }

  /* Video Titles */
  a.yt-simple-endpoint.style-scope.ytd-video-renderer {
    color: #f8d3da !important;
  }

  a.yt-simple-endpoint.style-scope.ytd-video-renderer:hover {
    color: #e34b73 !important;
  }

  /* Buttons and Links */
  a, .yt-simple-endpoint, .style-scope.ytd-button-renderer {
    color: #f8d3da !important;
  }

  .yt-simple-endpoint:hover, 
  .style-scope.ytd-button-renderer:hover {
    color: #e34b73 !important;
  }

  /* Player Area */
  .html5-video-container, 
  #movie_player {
    background-color: #1a1a1a !important;
  }

  .ytp-chrome-controls {
    background-color: #2e2e2e !important;
  }

  .ytp-chrome-controls .ytp-button:hover {
    color: #e34b73 !important;
  }

  /* Comments Section */
  #comments {
    background-color: #1a1a1a !important;
    color: #f8d3da !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
    background-color: #1a1a1a;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #e34b73;
    border-radius: 4px;
  }

  /* Search Box */
  #search {
    background-color: #2e2e2e !important;
    color: #f8d3da !important;
    border: 1px solid #e34b73 !important;
  }

  #search:hover, #search:focus {
    border-color: #f8d3da !important;
  }

  /* Miscellaneous */
  ytd-topbar-logo-renderer {
    filter: brightness(0.8);
  }
}
